export function mapLoadTickingArea(map) {
    switch (map) {
        case 0:
            return;
        case 1:
            overworld.runCommand("/tickingarea add -2346.07 4.99 -682.07 -2151.82 16.73 -782.59  daisy_cirkit true");
            overworld.runCommand("/tickingarea add -2262.32 8.50 -912.70 -2152.14 15.69 -783.82 daisy_cirkit2 true");
            system.runTimeout(() => {
                overworld.runCommand("/tickingarea remove daisy_cirkit");
                overworld.runCommand("/tickingarea remove daisy_cirkit2");
            }, 20 * (mapLoadTime + 1));
            break;
        case 2:
            overworld.runCommand("/tickingarea add -1556.41 12.00 -1191.58 -1482.44 44.00 -1358.63 coconutmall1 true");
            overworld.runCommand("/tickingarea add -1366.65 12.00 -1191.47 -1482.44 44.00 -1358.63 coconutmall2 true");
            overworld.runCommand("/tickingarea add -1352.12 54.58 -1354.80 -1599.92 11.00 -1427.79 coconutmall3 true");  
            overworld.runCommand("/tickingarea add -1369.47 45.80 -1399.69 -1428.30 6.07 -1276.47 coconutmall4 true");
            system.runTimeout(() => {
                overworld.runCommand("/tickingarea remove coconutmall1");
                overworld.runCommand("/tickingarea remove coconutmall2");
                overworld.runCommand("/tickingarea remove coconutmall3");
                overworld.runCommand("/tickingarea remove coconutmall4");
            }, 20 * (mapLoadTime + 1));
            break;
        case 4:
            overworld.runCommand("/tickingarea add -2537.05 7.09 425.86 -2423.20 11.85 288.70 yoshicirkit1 true");
            overworld.runCommand("/tickingarea add -2424.82 10.76 220.99 -2282.55 20.39 341.30 yoshicirkit2 true");
            overworld.runCommand("/tickingarea add -2283.48 14.56 339.56 -2435.10 16.12 427.72 yoshicirkit3 true");
            system.runTimeout(() => {
                overworld.runCommand("/tickingarea remove yoshicirkit1");
                overworld.runCommand("/tickingarea remove yoshicirkit2");
                overworld.runCommand("/tickingarea remove yoshicirkit3");
            }, 20 * (mapLoadTime + 1));
        case 5:
            overworld.runCommand("/tickingarea add -2076.99 4.00 1220.56 -2232.70 18.00 1317.70 sunsetWildsStage1 true");
            overworld.runCommand("/tickingarea add -2232.70 4.00 1317.70 -2087.92 18.00 1357.05 sunsetWildsStage2 true");
            system.runTimeout(() => {
                overworld.runCommand("/tickingarea remove sunsetWildsStage1");
                overworld.runCommand("/tickingarea remove sunsetWildsStage2");
            }, 20 * (mapLoadTime + 1));
            break;
    }
}